UPDATE page_text SET text_en = 'Depot Drop', text_ar = 'مواقع المستودعات' WHERE page = 'game' AND block = 'title';
UPDATE page_text SET text_en = 'Three warehouses, one city, a river in the way. Place them so every delivery travels the shortest total distance. A new city every Monday.', text_ar = 'ثلاثة مستودعات، ومدينة واحدة، ونهر يعترض الطريق. ضعها بحيث تقطع كل طلبات التوصيل أقصر مسافة إجمالية. مدينة جديدة كل يوم اثنين.' WHERE page = 'game' AND block = 'intro';
UPDATE page_text SET text_en = '- Tap 3 empty squares to place your warehouses. Tap a warehouse to pick it up again.
- Each house is served by its nearest warehouse. Trucks drive square by square, cross the river only on a bridge, and cannot go through buildings.
- The number on a house is how many deliveries it needs: its distance counts that many times.
- Your total distance updates as you play. Score: 1000 for the best possible layout, less the further you are from it.
- Ties go to whoever finished faster. The clock starts when you press Start. One scored try per week.', text_ar = '- اضغط على 3 مربّعات فارغة لوضع مستودعاتك. اضغط على مستودع لرفعه مرة أخرى.
- يخدم كل منزلٍ أقربُ مستودع إليه. تسير الشاحنات مربّعًا تلو الآخر، ولا تعبر النهر إلا على جسر، ولا تمرّ عبر المباني.
- الرقم على المنزل هو عدد طلبات التوصيل التي يحتاجها: تُحتسب مسافته بعدد هذه الطلبات.
- تتحدّث مسافتك الإجمالية أثناء اللعب. النتيجة: 1000 لأفضل توزيع ممكن، وأقل كلما ابتعدت عنه.
- عند التعادل يفوز الأسرع. يبدأ الوقت عند الضغط على «ابدأ». محاولة واحدة محتسبة كل أسبوع.' WHERE page = 'game' AND block = 'rules';
UPDATE page_text SET text_en = 'Where would you put three warehouses?', text_ar = 'أين تضع ثلاثة مستودعات؟' WHERE page = 'game' AND block = 'cta_title';
UPDATE page_text SET text_en = 'A new city every Monday, and only one perfect layout. Climb the leaderboard.', text_ar = 'مدينة جديدة كل يوم اثنين، وتوزيع مثالي واحد فقط. تقدّم في لوحة الصدارة.' WHERE page = 'game' AND block = 'cta_text';
